    Bug 1924728 - Make isGroupedByHeaderAtIndex work properly when the view is already closed. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D225640

diff --git a/mail/base/test/browser/browser_groupedBySortPersistence.js b/mail/base/test/browser/browser_groupedBySortPersistence.js
index ff6a3fa5e00..a3d4b219d2a 100644
--- a/mail/base/test/browser/browser_groupedBySortPersistence.js
+++ b/mail/base/test/browser/browser_groupedBySortPersistence.js
@@ -102,6 +102,9 @@ const subTest = async folder => {
     "The tree view should still be grouped by sort"
   );

+  // Select a group header to test for bug 1924728.
+  about3Pane.threadTree.selectedIndex = 0;
+
   // Disable grouped by sort.
   about3Pane.sortController.sortThreadPane("dateCol");
   await BrowserTestUtils.waitForCondition(
@@ -109,6 +112,13 @@ const subTest = async folder => {
     "The tree view should not be grouped by sort anymore"
   );

+  // Selections for group headers should not be persisted.
+  Assert.equal(
+    about3Pane.threadTree.selectedIndex,
+    -1,
+    "No row should be selected anymore."
+  );
+
   // Switch to another folder and back again. Grouped by sort should remain
   // disabled.
   about3Pane.displayFolder(rootFolder);
diff --git a/mail/modules/DBViewWrapper.sys.mjs b/mail/modules/DBViewWrapper.sys.mjs
index 7e500ba038e..cf2c69d5d25 100644
--- a/mail/modules/DBViewWrapper.sys.mjs
+++ b/mail/modules/DBViewWrapper.sys.mjs
@@ -2114,16 +2114,14 @@ DBViewWrapper.prototype = {
   },

   /**
-   * @returns {boolean} true if the row at the given index is a grouped view dummy header
-   *   row, false if anything else.
+   * Check if the row at the given index is the header (dummy row) of a group.
+   *
+   * @param {integer} aViewIndex - The index of a selected row.
+   * @returns {boolean} true if the row at the given index is a grouped view
+   *   dummy header row, false if anything else.
    */
   isGroupedByHeaderAtIndex(aViewIndex) {
-    if (
-      !this.dbView ||
-      aViewIndex < 0 ||
-      aViewIndex >= this.dbView.rowCount ||
-      !this.showGroupedBySort
-    ) {
+    if (!this.dbView || aViewIndex < 0 || aViewIndex >= this.dbView.rowCount) {
       return false;
     }
     return Boolean(this.dbView.getFlagsAt(aViewIndex) & MSG_VIEW_FLAG_DUMMY);
